import 'dart:async';import 'package:dio/dio.dart';import '../constants/app_constants.dart';import 'token_storage.dart';
class ApiClient{final TokenStorage tokens;late final Dio dio;Completer<bool>?_refreshing;ApiClient(this.tokens){dio=Dio(BaseOptions(baseUrl:AppConstants.apiBaseUrl,connectTimeout:const Duration(seconds:15),receiveTimeout:const Duration(seconds:25),headers:{'Accept':'application/json'}));dio.interceptors.add(InterceptorsWrapper(onRequest:(o,h)async{final token=await tokens.access;if(token!=null)o.headers['Authorization']='Bearer $token';h.next(o);},onError:(e,h)async{if(e.response?.statusCode==401&&e.requestOptions.extra['retried']!=true&&await _refresh()){try{final o=e.requestOptions;o.extra['retried']=true;o.headers['Authorization']='Bearer ${await tokens.access}';return h.resolve(await dio.fetch(o));}catch(_){}}h.next(e);}));}
 Future<bool>_refresh()async{if(_refreshing!=null)return _refreshing!.future;_refreshing=Completer<bool>();try{final token=await tokens.refresh;if(token==null){_refreshing!.complete(false);return false;}final plain=Dio(BaseOptions(baseUrl:AppConstants.apiBaseUrl));final r=await plain.post('/auth/refresh',data:{'refreshToken':token});await tokens.save(r.data['accessToken'],r.data['refreshToken']);_refreshing!.complete(true);return true;}catch(_){await tokens.clear();_refreshing!.complete(false);return false;}finally{_refreshing=null;}}
}
